CREATE TABLE IF NOT EXISTS mig_acuerdos_origen_revision (post_id BIGINT NOT NULL PRIMARY KEY, titulo TEXT, fecha_publicacion_wp DATETIME NULL, tipo VARCHAR(40), estado_wp VARCHAR(30), url TEXT, categorias TEXT, categoria_principal VARCHAR(255), fecha_sugerida DATE NULL, revision VARCHAR(40)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
